import{_ as s,o as i,c as n,ah as a}from"./chunks/framework.QnJvYzEf.js";const r="/projects/TurboPi/en/advanced/assets/image1.DxSdojJO.png",o="/projects/TurboPi/en/advanced/assets/image2.C5ZgeJN3.png",l="data:image/jpeg;base64,",c="/projects/TurboPi/en/advanced/assets/image4.CRsGpRxI.png",h="/projects/TurboPi/en/advanced/assets/image5.Jk_Ezsvh.png",d="/projects/TurboPi/en/advanced/assets/image6.ht43AUU0.png",g="/projects/TurboPi/en/advanced/assets/image7.DnwrTVif.png",p="/projects/TurboPi/en/advanced/assets/image8.BkqzGNru.png",m="/projects/TurboPi/en/advanced/assets/image9.TeB_tcJF.png",w="/projects/TurboPi/en/advanced/assets/image10.Bqy2eZq_.png",A="/projects/TurboPi/en/advanced/assets/image11.DfxOCizM.png",u="/projects/TurboPi/en/advanced/assets/image1.DxSdojJO.png",e="/projects/TurboPi/en/advanced/assets/image2.C5ZgeJN3.png",b="/projects/TurboPi/en/advanced/assets/image3.DKR6FwDN.png",_="/projects/TurboPi/en/advanced/assets/image4.DmamQAz0.png",y="/projects/TurboPi/en/advanced/assets/image5.8Q4hRmn6.png",f="/projects/TurboPi/en/advanced/assets/image6._TJNX5tb.png",N="/projects/TurboPi/en/advanced/assets/image8.DoO1urj0.png",k="/projects/TurboPi/en/advanced/assets/image11.CqkV501L.png",P="/projects/TurboPi/en/advanced/assets/image12.Bop_b8cY.png",C="/projects/TurboPi/en/advanced/assets/image1.r-1QbRAh.jpeg",Q="/projects/TurboPi/en/advanced/assets/image14.zJKqChxN.png",W=JSON.parse('{"title":"7. Robot Network Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"docs/7.Robot_Network_Configuration.md","filePath":"docs/7.Robot_Network_Configuration.md"}'),D={name:"docs/7.Robot_Network_Configuration.md"};function T(v,t,E,x,B,F){return i(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="_7-robot-network-configuration" tabindex="-1">7. Robot Network Configuration <a class="header-anchor" href="#_7-robot-network-configuration" aria-label="Permalink to &quot;7. Robot Network Configuration&quot;">​</a></h1><h2 id="_7-1-change-the-wi-fi-name-and-password" tabindex="-1">7.1 Change the Wi-Fi Name and Password <a class="header-anchor" href="#_7-1-change-the-wi-fi-name-and-password" aria-label="Permalink to &quot;7.1 Change the Wi-Fi Name and Password&quot;">​</a></h2><p>A computer normally connects to a Raspberry Pi hotspot with a name that begins with <strong>HW</strong>. Multiple TurboPi robots nearby can cause a connection to the wrong hotspot. This section explains how to change the default Wi-Fi name and password.</p><ol><li>Power on TurboPi. Connect the computer to the hotspot generated by TurboPi. The hotspot name normally begins with <strong>HW</strong>. Enter the password <strong>hiwonder</strong> for the first connection.</li></ol><img loading="lazy" height="138" width="359" src="'+r+'" style="width:800px;" class="common_img"><ol start="2"><li>Establish a VNC connection to TurboPi.</li></ol><img loading="lazy" height="1033" width="1782" src="'+o+'" style="width:800px;" class="common_img"><ol start="3"><li>Click the <img loading="lazy" height="37" width="50" src="'+l+'" class="inline-icon"> icon on the desktop or press <strong>Ctrl+Alt+T</strong> to open a terminal.</li></ol><img loading="lazy" height="212" width="751" src="'+c+'" style="width:800px;" class="common_img"><ol start="4"><li>In the terminal, enter <code>cd hiwonder-toolbox</code> and press <strong>Enter</strong> to go to the directory containing the Wi-Fi configuration file.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hiwonder-toolbox</span></span></code></pre></div><ol start="5"><li>Enter <code>sudo vim wifi_conf.py</code> to open the Wi-Fi configuration file in the editor.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_conf.py</span></span></code></pre></div><ol start="6"><li>The interface appears as shown below.</li></ol><img loading="lazy" height="234" width="702" src="'+h+'" style="width:800px;" class="common_img"><ol start="7"><li>Enter <code>:set number</code> and press <strong>Enter</strong> to display line numbers as needed.</li></ol><img loading="lazy" height="132" width="702" src="'+d+'" style="width:800px;" class="common_img"><ol start="8"><li>Press <strong>i</strong>. The <code>-- INSERT --</code> indicator appears in the lower-left corner. Edit the settings as needed.</li></ol><img loading="lazy" height="446" width="700" src="'+g+'" style="width:800px;" class="common_img"><ol start="9"><li>To change the Raspberry Pi Wi-Fi name to <strong>HW-TurboPi</strong> and the password to <strong>123456789</strong>, modify the program as shown below.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Set the Wi-Fi name and password as needed. Follow these rules:</strong></p><ul><li><p><strong>The Wi-Fi name must differ from the name of any existing router and must begin with &quot;HW&quot;.</strong></p></li><li><p><strong>The password must contain at least 8 characters.</strong></p></li></ul><p><strong>To restore the original settings, reverse the operation.</strong></p></div><img loading="lazy" height="191" width="700" src="'+p+'" style="width:800px;" class="common_img"><ol start="10"><li>After making the changes, press <strong>Esc</strong>. Enter <code>:wq</code> to save and exit the file.</li></ol><img loading="lazy" height="448" width="701" src="'+m+'" style="width:800px;" class="common_img"><ol start="11"><li>Enter <code>sudo systemctl restart hw_wifi.service</code> in the terminal. VNC automatically disconnects, and the Wi-Fi service restarts.</li></ol><img loading="lazy" height="179" width="699" src="'+w+'" style="width:800px;" class="common_img"><ol start="12"><li>Wait for the device to finish restarting. Connect the computer to the <strong>HW-TurboPi</strong> network using the password <strong>123456789</strong>.</li></ol><img loading="lazy" height="451" width="989" src="'+A+'" style="width:600px;" class="common_img"><ol start="13"><li><p>After the connection succeeds, wait for VNC to refresh.</p></li><li><p>After the connection succeeds, the VNC remote desktop appears as shown below.</p></li></ol><img loading="lazy" height="1033" width="1782" src="'+o+'" style="width:800px;" class="common_img"><h2 id="_7-2-change-the-network-connection-mode" tabindex="-1">7.2 Change the Network Connection Mode <a class="header-anchor" href="#_7-2-change-the-network-connection-mode" aria-label="Permalink to &quot;7.2 Change the Network Connection Mode&quot;">​</a></h2><p>The previous lessons explained how to connect the robot through the mobile app in LAN mode. This section explains how to switch to LAN mode by modifying the Wi-Fi configuration file.</p><p>To switch back to AP mode after making the change, reverse the operations below.</p><ol><li>Power on the robot. Connect the computer to the hotspot generated by the robot. The hotspot name normally begins with <strong>HW</strong>.</li></ol><img loading="lazy" height="138" width="359" src="'+u+'" style="width:600px;" class="common_img"><ol start="2"><li>Establish a VNC connection to the robot.</li></ol><img loading="lazy" height="1033" width="1782" src="'+e+'" style="width:800px;" class="common_img"><ol start="3"><li>Click the <img loading="lazy" height="76" width="67" src="'+b+'" class="inline-icon"> icon on the desktop to open the WiFi Tool PC software.</li></ol><img loading="lazy" height="343" width="722" src="'+_+'" style="width:800px;" class="common_img"><ol start="4"><li>Click <strong>Switch to LAN</strong> in the PC software.</li></ol><img loading="lazy" height="344" width="722" src="'+y+'" style="width:800px;" class="common_img"><ol start="5"><li>Enter the LAN Wi-Fi name in <strong>WiFi SSID</strong> and the password in <strong>WiFi Password</strong>. Then click <strong>Restart WiFi</strong> to switch to LAN mode.</li></ol><img loading="lazy" height="343" width="722" src="'+f+'" style="width:800px;" class="common_img"><ol start="6"><li><p>VNC automatically disconnects. When the TurboPi LED2 remains steadily on, the switch to LAN mode has succeeded.</p></li><li><p>To switch back to AP mode later, click <strong>Switch to Direct</strong> in the WiFi Tool PC software.</p></li><li><p>Click <strong>Restart WiFi</strong> to switch to AP mode.</p></li></ol><img loading="lazy" height="306" width="648" src="'+N+'" style="width:800px;" class="common_img"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>This example connects to &quot;Hiwonder&quot;. Set a different network as needed.</strong></p></li><li><p><strong>Do not use a public network, and ensure that the Wi-Fi name contains only English characters.</strong></p></li></ul></div><ol start="9"><li>To view the Raspberry Pi IP address in the mobile app, first connect the phone to the same LAN named <strong>Hiwonder</strong>.</li></ol><img loading="lazy" height="867" width="1049" src="'+k+'" style="width:400px;" class="common_img"><ol start="10"><li>Open the <strong>WonderPi</strong> app. Select <strong>Basic</strong>, then select <strong>TurboPi</strong>.</li></ol><img loading="lazy" height="378" width="746" src="'+P+'" style="width:800px;" class="common_img"><ol start="11"><li>The app automatically connects to the device. Wait until the icon shown below appears to confirm a successful connection.</li></ol><img loading="lazy" src="'+C+'" style="width:800px;" class="common_img"><ol start="12"><li>Press and hold the robot icon in the app to view the IP address and ID assigned to the robot.</li></ol><img loading="lazy" height="585" width="1268" src="'+Q+'" style="width:800px;" class="common_img"><ol start="13"><li>Open the VNC software. Enter the IP address <strong>192.168.11.109</strong> and establish a connection. After the connection succeeds, the VNC remote desktop appears as shown below.</li></ol><img loading="lazy" height="1033" width="1782" src="'+e+'" style="width:800px;" class="common_img">',56)])])}const S=s(D,[["render",T]]);export{W as __pageData,S as default};
